<?php
namespace ZinCelestial\Platform\GovernanceDashboard;defined('ABSPATH')||exit;
final class GovernanceDashboardService{public function __construct(private \wpdb $db,private string $audit,private int $site_id){}public function summary():array{$rows=$this->db->get_results($this->db->prepare("SELECT event,COUNT(*) total FROM {$this->audit} WHERE site_id=%d AND created_at>=DATE_SUB(UTC_TIMESTAMP(),INTERVAL 30 DAY) GROUP BY event",$this->site_id),ARRAY_A);$events=[];foreach((array)$rows as $r)$events[sanitize_key($r['event'])]=(int)$r['total'];return['site_id'=>$this->site_id,'events'=>$events,'generated_at'=>time()];}public function timeline(int $limit=50):array{$limit=max(1,min(100,$limit));$rows=$this->db->get_results($this->db->prepare("SELECT sequence_id,event,actor_id,key_id,entry_hash,created_at FROM {$this->audit} WHERE site_id=%d ORDER BY sequence_id DESC LIMIT %d",$this->site_id,$limit),ARRAY_A);return array_map(fn($r)=>['sequence_id'=>(int)$r['sequence_id'],'event'=>sanitize_key($r['event']),'actor_id'=>(int)$r['actor_id'],'key_id'=>sanitize_key($r['key_id']),'entry_hash'=>substr($r['entry_hash'],0,12).'…','created_at'=>$r['created_at']],(array)$rows);}}
